61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic email validation: a non-empty local part, a single '@', and a
68	     * domain with at least one dot-separated label ending in a letter-only TLD.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
72	
73	    /**
74	     * Disposable / throw-away email domains whose owners are rejected: an email on one of these
75	     * domains is treated as invalid input and rejected with 400. Compared case-insensitively.
76	     */
77	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
78	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
79	
80	    /**
81	     * Fixed public-holiday list. A registration date that lands on one of these is not a business
82	     * day and is rolled forward to the next non-holiday weekday.
83	     */
84	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS =
85	        java.util.Set.of(
86	            LocalDate.of(2026, 1, 1),
87	            LocalDate.of(2026, 1, 26),
88	            LocalDate.of(2026, 4, 25),
89	            LocalDate.of(2026, 12, 25),
90	            LocalDate.of(2026, 12, 28));
91	
92	    /** Dedicated audit logger for owner lifecycle side-effects. */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    private final ClinicService clinicService;
96	
97	    private final OwnerMapper ownerMapper;
98	
99	    private final PetMapper petMapper;
100	
101	    private final VisitMapper visitMapper;
