103	    public OwnerRestControllerV1(ClinicService clinicService,
104	                                 OwnerMapper ownerMapper,
105	                                 PetMapper petMapper,
106	                                 VisitMapper visitMapper) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	    }
112	
113	    /**
114	     * Normalise a raw telephone number to E.164 form.
115	     *
116	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
117	     * code are kept when present; otherwise country code '+61' is assumed and a
118	     * single leading '0' is dropped from the national digits. The result must have
119	     * between 8 and 15 digits after the '+'.
120	     *
121	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
122	     * national-number length is additionally validated against that country code:
123	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
124	     * length is wrong for its country is rejected.
125	     *
126	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
127	     */
128	    static String toE164(String raw) {
129	        if (raw == null) {
130	            return null;
131	        }
132	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
133	        String digits;
134	        boolean explicitCountryCode;
135	        if (cleaned.startsWith("+")) {
136	            digits = cleaned.substring(1);
137	            explicitCountryCode = true;
138	        } else {
139	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
140	            digits = "61" + national;
141	            explicitCountryCode = false;
142	        }
143	        if (!digits.matches("[0-9]{8,15}")) {
144	            return null;
145	        }
146	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
147	            return null;
148	        }
149	        return "+" + digits;
150	    }
151	
152	    /**
153	     * Validate the national-number length of an E.164 number (its digits without the
154	     * leading '+') against the requirement for its country code: country code '+61'
155	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
156	     * without a configured length requirement are accepted unchanged.
157	     */
158	    private static boolean hasValidNationalLength(String digits) {
159	        if (digits.startsWith("61")) {
160	            return digits.length() - "61".length() == 9;
161	        }
162	        if (digits.startsWith("1")) {
163	            return digits.length() - "1".length() == 10;
164	        }
165	        return true;
166	    }
167	
168	    /**
169	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
170	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
171	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
172	     * input normalises to the empty string.
173	     */
174	    private static String normaliseIdentity(String value) {
175	        if (value == null) {
176	            return "";
177	        }
178	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
179	    }
180	
181	    /**
182	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
183	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
184	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
185	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
186	     * that is both stored and used for every address comparison.
187	     */
188	    static String normaliseAddress(String value) {
189	        if (value == null) {
190	            return "";
191	        }
192	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
193	        if (collapsed.isEmpty()) {
194	            return "";
195	        }
196	        String[] tokens = collapsed.split(" ");
197	        StringBuilder result = new StringBuilder();
198	        for (int i = 0; i < tokens.length; i++) {
199	            if (i > 0) {
200	                result.append(' ');
201	            }
202	            result.append(expandAddressAbbreviation(tokens[i]));
203	        }
204	        return result.toString();
205	    }
206	
207	    /**
208	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
209	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
210	     * returned unchanged.
211	     */
212	    private static String expandAddressAbbreviation(String token) {
213	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
214	        return switch (core) {
215	            case "ST" -> "STREET";
216	            case "RD" -> "ROAD";
217	            case "AVE" -> "AVENUE";
218	            default -> token;
219	        };
220	    }
221	
222	    /**
223	     * Derive the stable, shared household identifier for owners in the same household: the first 12
224	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
225	     * so every owner with the same last name and postcode resolves to the same value regardless of
226	     * the order in which they were created.
227	     */
228	    private static String householdId(String lastNameKey, String postcode) {
229	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
230	    }
231	
232	    /**
233	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
234	     * name and postcode). An owner without a postcode has no household peers and counts as a household
235	     * of one.
236	     */
237	    private int householdSize(Owner owner) {
238	        if (owner.getPostcode() == null) {
239	            return 1;
240	        }
241	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
242	        return (int) this.clinicService.findAllOwners().stream()
243	            .filter(existing -> existing.getPostcode() != null
244	                && householdId.equals(
245	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
246	            .count();
247	    }
248	
249	    /**
250	     * Build an owner's derived duplicate-detection identity key as
251	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
252	     * component contributes the empty string, and the email is lower-cased so the comparison is
253	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
254	     */
255	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
256	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
257	        String emailKey = email == null ? "" : email.toLowerCase();
258	        String household = householdId == null ? "" : householdId;
259	        return telephone + "|" + emailKey + "|" + household;
260	    }
261	
262	    /**
263	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
264	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
265	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
266	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
267	     * only on the owner's own region and identity, not on how many owners already exist.
268	     */
269	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
270	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
271	    }
272	
273	    /**
274	     * De-duplicate a computed customer code against the codes already assigned to existing owners:
275	     * when {@code code} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
276	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
277	     */
278	    private String deduplicateCustomerCode(String code) {
279	        Set<String> existing = this.clinicService.findAllOwners().stream()
280	            .map(Owner::getCustomerCode)
281	            .filter(Objects::nonNull)
282	            .collect(Collectors.toSet());
283	        if (!existing.contains(code)) {
284	            return code;
285	        }
286	        int n = 2;
287	        while (existing.contains(code + "-" + n)) {
288	            n++;
289	        }
290	        return code + "-" + n;
291	    }
292	
293	    /**
294	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
295	     */
296	    private static String hash8(String input) {
297	        return hashHex(input, 8, true);
298	    }
299	
300	    /**
301	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
302	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
303	     */
304	    private static String hashHex(String input, int length, boolean upperCase) {
305	        try {
306	            byte[] digest = MessageDigest.getInstance("SHA-256")
307	                .digest(input.getBytes(StandardCharsets.UTF_8));
308	            StringBuilder sb = new StringBuilder(digest.length * 2);
309	            for (byte b : digest) {
310	                sb.append(String.format("%02x", b));
311	            }
312	            String hex = sb.substring(0, length);
313	            return upperCase ? hex.toUpperCase() : hex;
314	        }
315	        catch (java.security.NoSuchAlgorithmException e) {
316	            throw new IllegalStateException(e);
317	        }
318	    }
319	
320	    /**
321	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
322	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
323	     * fixed city-to-region table, else {@code "UNKNOWN"}.
324	     */
325	    private static String region(String postcode, String city) {
326	        String fromPostcode = regionForPostcode(postcode);
327	        return fromPostcode != null ? fromPostcode : regionForCity(city);
328	    }
329	
330	    /**
331	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
332	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
333	     */
334	    private static String regionForPostcode(String postcode) {
335	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
336	            return null;
337	        }
338	        int value = Integer.parseInt(postcode);
339	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
340	            int[] range = entry.getValue();
341	            if (value >= range[0] && value <= range[1]) {
342	                return entry.getKey();
343	            }
344	        }
345	        return null;
346	    }
347	
348	    /**
349	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
350	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
351	     * weekday; ordinary weekday dates are returned unchanged.
352	     */
353	    static LocalDate toBusinessDay(LocalDate date) {
354	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
355	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
356	            || PUBLIC_HOLIDAYS.contains(date)) {
357	            date = date.plusDays(1);
358	        }
359	        return date;
360	    }
361	
362	    /**
363	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
364	     * using the same per-day accumulation path as the daily create-limit rule.
365	     */
366	    private long ownersCreatedOn(LocalDate registrationDate) {
367	        LocalDate day = toBusinessDay(registrationDate);
368	        return this.clinicService.findAllOwners().stream()
369	            .map(Owner::getRegistrationDate)
370	            .filter(existing -> existing != null)
371	            .map(OwnerRestControllerV1::toBusinessDay)
372	            .filter(day::equals)
373	            .count();
374	    }
375	
376	    /**
377	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
378	     * postcode against the owner's city region.
379	     */
380	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
381	        "NSW", new int[] {2000, 2099},
382	        "VIC", new int[] {3000, 3099},
383	        "QLD", new int[] {4000, 4099});
384	
385	    /**
386	     * Resolve an owner's region from the city using the fixed city-to-region table
387	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
388	     * when the city is not listed.
389	     */
390	    private static String regionForCity(String city) {
391	        return switch (city == null ? "" : city) {
392	            case "Sydney" -> "NSW";
393	            case "Melbourne" -> "VIC";
394	            case "Brisbane" -> "QLD";
395	            default -> "UNKNOWN";
396	        };
397	    }
398	
399	    /**
400	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
401	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
402	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
403	     */
404	    private static boolean isPostcodeValid(String postcode, String city) {
405	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
406	            return false;
407	        }
408	        int[] range = REGION_POSTCODES.get(regionForCity(city));
409	        if (range == null) {
410	            return true;
411	        }
412	        int value = Integer.parseInt(postcode);
413	        return value >= range[0] && value <= range[1];
414	    }
415	
416	    /**
417	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
418	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
419	     */
420	    private static boolean isDisposableEmailDomain(String email) {
421	        if (email == null) {
422	            return false;
423	        }
424	        int at = email.lastIndexOf('@');
425	        if (at < 0 || at == email.length() - 1) {
426	            return false;
427	        }
428	        String domain = email.substring(at + 1).toLowerCase();
429	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
430	    }
431	
432	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
433	    @Override
434	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
435	        Collection<Owner> owners;
436	        if (lastName != null) {
437	            owners = this.clinicService.findOwnerByLastName(lastName);
438	        } else {
439	            owners = this.clinicService.findAllOwners();
440	        }
441	        if (owners.isEmpty()) {
442	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
443	        }
444	        owners.forEach(owner -> owner.setHouseholdSize(householdSize(owner)));
445	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
451	        Owner owner = this.clinicService.findOwnerById(ownerId);
452	        if (owner == null) {
453	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
454	        }
455	        owner.setHouseholdSize(householdSize(owner));
456	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
457	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
458	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
459	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
460	    }
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
465	        String telephone = toE164(ownerFieldsDto.getTelephone());
466	        if (telephone == null) {
467	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
468	        }
469	        String email = ownerFieldsDto.getEmail();
470	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
471	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
472	        }
473	        if (isDisposableEmailDomain(email)) {
474	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
475	        }
476	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
477	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
478	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
479	        // normalized addressLine2 appended after a single space when present.
480	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
481	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
482	        boolean structuredAddress = !addressLine1.isEmpty();
483	        String address;
484	        if (structuredAddress) {
485	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
486	        } else {
487	            address = normaliseAddress(ownerFieldsDto.getAddress());
488	        }
489	        if (address.isEmpty()) {
490	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
491	        }
492	        String postcode = ownerFieldsDto.getPostcode();
493	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
494	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
495	        }
496	        if (ownerFieldsDto.getRegistrationDate() != null
497	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
498	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
499	        }
500	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
501	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
502	        LocalDate registrationDate = toBusinessDay(effectiveDate);
503	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
504	            .map(Owner::getRegistrationDate)
505	            .filter(existing -> existing != null)
506	            .map(OwnerRestControllerV1::toBusinessDay)
507	            .filter(registrationDate::equals)
508	            .count();
509	        if (ownersCreatedThatDay >= 100) {
510	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
511	        }
512	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
513	        long ownersInCity = this.clinicService.findAllOwners().stream()
514	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
515	            .count();
516	        if (ownersInCity >= 50) {
517	            return new ResponseEntity<>(HttpStatus.CONFLICT);
518	        }
519	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
520	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
521	        // The household is deterministically keyed on (normalized last name, postcode): every owner
522	        // with a postcode belongs to the household identified by this computed id, and owners sharing
523	        // a last name and postcode share it automatically.
524	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
525	        // Existing owners already in this household (same last name and postcode). Soft-deleted
526	        // owners are ignored so a duplicate that only matches a deleted owner is allowed.
527	        List<Owner> householdMembers = (householdId == null) ? List.of()
528	            : this.clinicService.findAllOwners().stream()
529	                .filter(existing -> !existing.isDeleted())
530	                .filter(existing -> householdId.equals(
531	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
532	                .toList();
533	        // A second owner in an existing household is a household duplicate: rejected with 409 unless
534	        // it declares 'sharesHousehold', which only bypasses this block (the household link itself is
535	        // already assigned deterministically above).
536	        if (!householdMembers.isEmpty() && !sharesHousehold) {
537	            return new ResponseEntity<>(HttpStatus.CONFLICT);
538	        }
539	        String identityKey = identityKey(telephone, email, householdId);
540	        boolean identityInUse = this.clinicService.findAllOwners().stream()
541	            .filter(existing -> !existing.isDeleted())
542	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
543	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
544	        if (identityInUse) {
545	            return new ResponseEntity<>(HttpStatus.CONFLICT);
546	        }
547	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
548	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
549	            .filter(existing ->
550	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
551	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
552	            .count();
553	        HttpHeaders headers = new HttpHeaders();
554	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
555	        owner.setNamesakeCount(namesakeCount);
556	        owner.setAddress(address);
557	        if (structuredAddress) {
558	            owner.setAddressLine1(addressLine1);
559	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
560	        } else {
561	            owner.setAddressLine1(null);
562	            owner.setAddressLine2(null);
563	        }
564	        owner.setTelephone(telephone);
565	        owner.setEmail(email == null ? null : email.toLowerCase());
566	        owner.setRegistrationDate(registrationDate);
567	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
568	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
569	        owner.setHouseholdId(householdId);
570	        // A created owner is never flagged as a suspected duplicate: a lone owner has no household
571	        // peer, and a same-household owner can only be created by declaring 'sharesHousehold', which
572	        // makes it an intentional household member rather than a suspected duplicate.
573	        owner.setPossibleDuplicateOf(null);
574	        this.clinicService.saveOwner(owner);
575	        owner.setHouseholdSize(householdSize(owner));
576	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
577	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
578	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
579	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
580	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
581	        headers.setLocation(UriComponentsBuilder.newInstance()
582	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
583	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
584	    }
585	
586	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
587	    @Override
588	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
589	        String telephone = toE164(ownerFieldsDto.getTelephone());
590	        if (telephone == null) {
591	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
592	        }
593	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
594	        if (currentOwner == null) {
595	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
596	        }
597	        String email = ownerFieldsDto.getEmail();
598	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
599	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
600	        }
601	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
602	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
603	        if (!addressLine1.isEmpty()) {
604	            currentOwner.setAddressLine1(addressLine1);
605	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
606	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
607	        } else {
608	            currentOwner.setAddressLine1(null);
609	            currentOwner.setAddressLine2(null);
610	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
611	        }
612	        currentOwner.setCity(ownerFieldsDto.getCity());
613	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
614	        currentOwner.setLastName(ownerFieldsDto.getLastName());
615	        currentOwner.setTelephone(telephone);
616	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
617	        this.clinicService.saveOwner(currentOwner);
618	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
619	    }
620	
621	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
622	    @Transactional
623	    @Override
624	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
625	        Owner owner = this.clinicService.findOwnerById(ownerId);
626	        if (owner == null) {
627	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
628	        }
629	        // Soft delete: flag the owner deleted and retain the record so it can still be read back.
630	        owner.setDeleted(true);
631	        this.clinicService.saveOwner(owner);
632	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
633	    }
634	
635	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
636	    @Override
637	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
638	        Owner owner = this.clinicService.findOwnerById(ownerId);
639	        if (owner == null) {
640	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
641	        }
642	        HttpHeaders headers = new HttpHeaders();
643	        Pet pet = petMapper.toPet(petFieldsDto);
644	        owner.setId(ownerId);
645	        pet.setOwner(owner);
646	        pet.getType().setName(null);
647	        this.clinicService.savePet(pet);
648	        PetDto petDto = petMapper.toPetDto(pet);
649	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
650	            .buildAndExpand(pet.getId()).toUri());
651	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
652	    }
653	
654	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
655	    @Override
656	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
657	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
658	        if (currentOwner != null) {
659	            Pet currentPet = this.clinicService.findPetById(petId);
660	            if (currentPet != null) {
661	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
662	                currentPet.setName(petFieldsDto.getName());
663	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
664	                this.clinicService.savePet(currentPet);
665	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
666	            }
667	        }
668	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
669	    }
670	
671	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
672	    @Override
673	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
674	        HttpHeaders headers = new HttpHeaders();
675	        Visit visit = visitMapper.toVisit(visitFieldsDto);
676	        Pet pet = new Pet();
677	        pet.setId(petId);
678	        visit.setPet(pet);
679	        this.clinicService.saveVisit(visit);
680	        VisitDto visitDto = visitMapper.toVisitDto(visit);
681	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
682	            .buildAndExpand(visit.getId()).toUri());
683	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
684	    }
685	
686	
687	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
688	    @Override
689	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
690	        Owner owner = this.clinicService.findOwnerById(ownerId);
691	        if (owner != null) {
692	            Pet pet = owner.getPet(petId);
693	            if (pet != null) {
694	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
