92	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
93	     * When the customer code is absent it falls back to resolving the region directly, preferring the
94	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
95	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
96	     * {@code "UNKNOWN"} when neither resolves.
97	     */
98	    default String formatLocality(Owner owner) {
99	        if (owner == null) {
100	            return null;
101	        }
102	        String code = owner.getCustomerCode();
103	        if (code != null) {
104	            int dash = code.indexOf('-');
105	            if (dash > 0) {
