146	            return null;
147	        }
148	        int value = Integer.parseInt(postcode);
149	        if (value >= 2000 && value <= 2099) {
150	            return "NSW";
151	        }
152	        if (value >= 3000 && value <= 3099) {
153	            return "VIC";
154	        }
155	        if (value >= 4000 && value <= 4099) {
