166	    default Integer formatMembershipPoints(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        int points = 0;
171	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
172	        if (hasEmail) {
173	            points += 2;
174	        }
175	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
